function lastActionRequiresLogin(state = null, action) {
  switch (action.type) {
    case READER_REGISTER_LAST_ACTION_REQUIRES_LOGIN:
      return action.lastAction;
    default:
      return state;
  }
}

// Test: Dispatch a like action
const likeAction = {
  type: READER_REGISTER_LAST_ACTION_REQUIRES_LOGIN,
  lastAction: { type: 'like', siteId: 209044104, postId: 74582 }
};

let state = null;
state = lastActionRequiresLogin(state, likeAction);
console.log('State after dispatch:', JSON.stringify(state, null, 2));

// Simulate page reload (state resets to initial value)
const stateAfterReload = lastActionRequiresLogin(undefined, { type: 'INIT' });
console.log('State after reload:', stateAfterReload);
